\begin{lemma} \label{L: few that meet all}
 Let $A_1,\ldots,A_{n+1}$ be pairwise skew $(n-1)$-spaces of \PG(2n,q)$. The number of $n$-spaces that intersect every $A_i$ for $1\leq i\leq n+1$ is \mathcal{O(q^{n^2-1})$.
\end{lemma}

